def slice.unpack_from_u64
  (input : Std.U64) : RustM (Std.Usize × Std.Usize) := do
  let i ← 18446744069414584320#u64 >>> 32#i32
  let i1 ← lift (input &&& i)
  let i2 ← lift (UScalar.cast .Usize i1)
  let i3 ← lift (input &&& 4294967295#u64)
  let i4 ← lift (UScalar.cast .Usize i3)
  ok (i2, i4)
